// Title: C# example: Validate WordArt two‑color gradient colors in SVG exported by Aspose.Cells
// Common Searches: how to verify WordArt gradient colors after saving Excel as SVG with Aspose.Cells in C# | C# extract linearGradient stop colors from SVG generated by Aspose.Cells | compare original WordArt two‑color gradient fill with CSS linearGradient stops | validate that CSS gradient matches WordArt colors using Aspose.Cells export | regex pattern for finding linearGradient elements in SVG files created by Aspose.Cells
// Tags: Aspose.Cells export to SVG with WordArt gradient | parse linearGradient elements using C# regex | compare WordArt gradient fill to CSS gradient colors | validate two‑color gradient stop values in generated SVG | System.Drawing.Color comparison with CSS hex colors

using System;
using System.Drawing;
using System.IO;
using System.Text.RegularExpressions;
using Aspose.Cells;
using Aspose.Cells.Drawing;
using Aspose.Cells.Rendering;
using Aspose.Cells.Saving;

namespace AsposeCellsWordArtGradientValidator
{
    // The sample creates an Excel workbook, adds a WordArt shape with a vertical two‑color gradient, saves the workbook as SVG, reads the SVG file, uses regular expressions to locate the first <linearGradient> element, extracts the first and last stop colors, converts them to System.Drawing.Color, and checks whether they match the original start and end colors, reporting success or mismatch.
    class Program
    {
        static void Main(string[] args)
        {
            // Path for the temporary SVG file
            string svgPath = "WordArtGradient.svg";

            // Original gradient colors
            Color startColor = Color.FromArgb(255, 0, 0); // Red
            Color endColor   = Color.FromArgb(0, 0, 255); // Blue

            try
            {
                // ------------------------------------------------------------
                // 1. Create a workbook and add a WordArt shape with a gradient
                // ------------------------------------------------------------
                Workbook workbook = new Workbook();
                Worksheet sheet = workbook.Worksheets[0];

                // Add a WordArt shape (preset style does not affect the gradient)
                Shape wordArt = sheet.Shapes.AddWordArt(
                    PresetWordArtStyle.WordArtStyle1,
                    "Gradient WordArt",
                    2,          // top row
                    10,         // top offset (pixels)
                    2,          // left column
                    10,         // left offset (pixels)
                    200,        // height (pixels)
                    400);       // width (pixels)

                // Give the shape a recognizable name (helps debugging)
                wordArt.Name = "MyWordArt";

                // Apply a two‑color gradient fill to the shape
                wordArt.Fill.SetTwoColorGradient(startColor, endColor, GradientStyleType.Vertical, 1);

                // ------------------------------------------------------------
                // 2. Export the workbook to SVG (the SVG will contain CSS gradients)
                // ------------------------------------------------------------
                ImageSaveOptions svgOptions = new ImageSaveOptions(SaveFormat.Svg)
                {
                    // Ensure each sheet is rendered on a single page
                    ImageOrPrintOptions = { OnePagePerSheet = true, SvgCssPrefix = "wa-" }
                };

                // Save the workbook as SVG
                workbook.Save(svgPath, svgOptions);

                // ------------------------------------------------------------
                // 3. Load the generated SVG and extract the gradient definition
                // ------------------------------------------------------------
                if (!File.Exists(svgPath))
                {
                    Console.WriteLine($"SVG file was not created: {svgPath}");
                    return;
                }

                string svgContent;
                try
                {
                    svgContent = File.ReadAllText(svgPath);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Failed to read SVG file: {ex.Message}");
                    return;
                }

                // Find all <linearGradient> elements
                var gradientRegex = new Regex(
                    @"<linearGradient[^>]*id\s*=\s*[""'](?<id>[^""']+)[""'][^>]*>(?<stops>.*?)</linearGradient>",
                    RegexOptions.Singleline | RegexOptions.IgnoreCase);

                MatchCollection gradientMatches = gradientRegex.Matches(svgContent);
                if (gradientMatches.Count == 0)
                {
                    Console.WriteLine("No linearGradient elements were found in the SVG.");
                    return;
                }

                // For simplicity we assume the first gradient belongs to our WordArt.
                Match firstGradient = gradientMatches[0];
                string gradientId = firstGradient.Groups["id"].Value;
                string stopsBlock = firstGradient.Groups["stops"].Value;

                // Extract stop colors (order matters)
                var stopColorRegex = new Regex(
                    @"stop-color\s*:\s*#(?<hex>[0-9A-Fa-f]{6})",
                    RegexOptions.IgnoreCase);
                MatchCollection stopColorMatches = stopColorRegex.Matches(stopsBlock);

                if (stopColorMatches.Count < 2)
                {
                    Console.WriteLine($"Gradient '{gradientId}' does not contain at least two color stops.");
                    return;
                }

                // First and last stop colors
                string firstStopHex = stopColorMatches[0].Groups["hex"].Value;
                string lastStopHex  = stopColorMatches[stopColorMatches.Count - 1].Groups["hex"].Value;

                // Convert hex strings to System.Drawing.Color for comparison
                Color firstStopColor = ColorTranslator.FromHtml("#" + firstStopHex);
                Color lastStopColor  = ColorTranslator.FromHtml("#" + lastStopHex);

                // ------------------------------------------------------------
                // 4. Validate that the extracted colors match the original ones
                // ------------------------------------------------------------
                bool startMatches = ColorsAreEqual(startColor, firstStopColor);
                bool endMatches   = ColorsAreEqual(endColor,   lastStopColor);

                Console.WriteLine($"Gradient ID: {gradientId}");
                Console.WriteLine($"Original start color: {ColorToHex(startColor)}");
                Console.WriteLine($"Extracted first stop : {ColorToHex(firstStopColor)}  => {(startMatches ? "MATCH" : "MISMATCH")}");
                Console.WriteLine($"Original end color  : {ColorToHex(endColor)}");
                Console.WriteLine($"Extracted last stop  : {ColorToHex(lastStopColor)}   => {(endMatches ? "MATCH" : "MISMATCH")}");

                if (startMatches && endMatches)
                {
                    Console.WriteLine("Validation succeeded: CSS gradient matches the original WordArt color stops.");
                }
                else
                {
                    Console.WriteLine("Validation failed: CSS gradient does NOT match the original WordArt color stops.");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("An error occurred during processing:");
                Console.WriteLine(ex.Message);
            }
            finally
            {
                // Optional: clean up the temporary SVG file
                // if (File.Exists(svgPath)) File.Delete(svgPath);
            }
        }

        private static bool ColorsAreEqual(Color a, Color b)
        {
            return a.R == b.R && a.G == b.G && a.B == b.B;
        }

        private static string ColorToHex(Color c)
        {
            return $"#{c.R:X2}{c.G:X2}{c.B:X2}";
        }
    }
}
